scwin.resizeToWin = function() {
    //frame.Width = 280;
    //frame.Height = 420;
    $c.stf.MoveCenterOfParent();
};
scwin.fn_initForm = function(initTyp) {
    if (initTyp == 'I') {
        img_ISU_CD.src = "../img/btn_search.gif";
        img_ISU_CD.setDisabled(false);
    } else if (initTyp == 'X') {
        img_ISU_CD.src = "../img/btn_search_d.gif";
        img_ISU_CD.setDisabled(true);
    }
};
scwin.fn_setSumblComponent = function() {
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == '1') {
        ibx_ISU_ENG_SYMBL.setReadOnly(false);
        //ibx_ISU_ENG_SYMBL.ReadOnlyBackgroundColor = '#ffffff';
        img_ISU_ENG_SYMBL.show("");
    } else {
        ibx_ISU_ENG_SYMBL.setReadOnly(true);
        //ibx_ISU_ENG_SYMBL.ReadOnlyBackgroundColor = '#b9d4f7';
        img_ISU_ENG_SYMBL.hide();
    }
};
scwin.fn_setInitLabel = function() {
    if (scwin.vSecugrpID == $c.lc.getGlbValue("SECUGRP_ID_DR")) {
        scwin.visuShrsLabelNm = "DR";
        lb_PARVAL.setValue('DR당액면가');
        lb_BF_ACC_ISU_SHRS.setValue('변경전 상장DR수');
        lb_ISU_SHRS.setValue('증감상장DR수');
        lb_ACC_ISU_SHRS.setValue('변경후 상장DR수');
        panel_PARVAL.hide();
        panel_ISU_CAP.hide();
    } else {
        scwin.visuShrsLabelNm = "주식";
        panel_PARVAL.show("");
        panel_ISU_CAP.show("");
    }
    if (scwin.vSecugrpID == $c.lc.getGlbValue("SECUGRP_ID_DR") || scwin.vSecugrpID == $c.lc.getGlbValue("SECUGRP_ID_FS")) {
        edt_PARVAL.MaxDecimalPlace = 3;
        ibx_ISU_CAP.MaxDecimalPlace = 3;
    } else {
        edt_PARVAL.MaxDecimalPlace = 0;
        ibx_ISU_CAP.MaxDecimalPlace = 0;
    }
};
scwin.fn_SetComboCode = function() {
    ibx_NPARVALSTK_YN.CBData = scwin.strCbd_NPARVALSTK_YN;
    ibx_NPARVALSTK_YN.setSelectedIndex(0);
    edt_PARVAL.show("");
    ibx_PER1STK_CAP.hide();
    ibx_PER1STK_CAP.setValue("0");

    //var url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listStkIsuRsnCd&inputMessageId=STK_ISU_RSN_CD_OUT";
    //url += "&LD_MKT_TP_CD=" + scwin.vSPOT_ISU_TRD_MKT_TP_CD;
    //발행사유코드
    //dts_STK_ISU_RSN_CD.DataID = encodeURI(url);
    //dts_STK_ISU_RSN_CD.Reset();
    const sbmOptions = {
        id: "sbm_selectListStockIsuRsn",
        action: "/api/listing/common/code/select-list-stock-isu-rsn?ldMktTpCd=" + scwin.vSPOT_ISU_TRD_MKT_TP_CD,
        method: "get",
        // ref: "dma_codReq",
        target: "dlt_listStockIsuRsn=body",
        // submitDoneHandler: scwin.sbm_listCodeValue_submitdone,
        isProcessMsg: false
    };
    $c.sbm.executeDynamic(sbmOptions);
};
scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = scwin.vSecugrpID;
    arrPar[1] = ibx_ISUR_CD.getValue(); // 코드값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    //var dbClickYn =  arrPar[0].DBCLICKYN;
    if (arrPar[0].ISU_CD != "") {
        ibx_ISU_CD.setValue(arrPar[0].ISU_CD);
        ibx_ISU_KOR_NM.setValue(arrPar[0].ISU_KOR_NM);
        ibx_ISU_KOR_ABBRV.setValue(arrPar[0].ISU_KOR_ABBRV);
        ibx_ISU_ENG_NM.setValue(arrPar[0].ISU_ENG_NM);
        ibx_ISU_ENG_ABBRV.setValue(arrPar[0].ISU_ENG_ABBRV);
        ibx_ISU_SRT_CD.setValue(arrPar[0].ISU_SRT_CD);
        ibx_ISU_ENG_SYMBL.setValue(arrPar[0].ISU_ENG_SYMBL);
        sbx_CURR_ISO_CD.setValue(arrPar[0].CURR_ISO_CD);
        if (scwin.vSecugrpID == $c.lc.getGlbValue("SECUGRP_ID_DR")) {
            ibx_STKCERT_KIND_CD.setValue('KDR'); //주식의종류코드를 셋팅
        } else if (scwin.vSecugrpID == $c.lc.getGlbValue("SECUGRP_ID_FS")) {
            ibx_STKCERT_KIND_CD.setValue('000'); //주식의종류코드를 셋팅
        } else {
            ibx_STKCERT_KIND_CD.setValue(ibx_ISU_CD.getValue().substring(8, 11)); //주식의종류코드를 셋팅
        }

        scwin.fn_nprefstk_read_sync(ibx_ISU_CD.getValue());
        scwin.fn_bf_read_sync();
    }
};



/**
 * 변경전 주식수, 자본금 가져오기
 */
scwin.fn_bf_read_sync = async function() {
    //var url = "/Newlisting.do?method=selectManagement&inputMessageId=BF_STKCERT_ISU_DTL_OUT";
    //url += "&DIV_IDX=" + DIV_R_LISTING_BF_ISU;
    //url += "&ISU_CD=" + $c.stf.getObjectValue(ibx_ISU_CD);
    //url += "&LIST_DD=" + $c.stf.getObjectValue(ibx_LIST_DD);
    //dtsObj.DataID = encodeURI(url);
    //dtsObj.reset();

    dma_bfStkcertIsuOneReq.set("isuCd", ibx_ISU_CD.getValue());
    dma_bfStkcertIsuOneReq.set("listDd", ibx_LIST_DD.getValue());

    const sbmOptions = {
        id: "sbm_selectOneBeforeStkcertIsu",
        action: "/api/listing/lstproc/newlist-isu/select-one-before-stkcert-isu",
        method: "get",
        ref: "dma_bfStkcertIsuOneReq",
        target: "dma_bfStkcertIsuOneRes=body",
        // submitDoneHandler: scwin.sbm_listCodeValue_submitdone,
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (!$c.util.isEmpty(dma_bfStkcertIsuOneRes.get("bfAccIsuShrs")) && 
            !$c.util.isEmpty(dma_bfStkcertIsuOneRes.get("bfAccIsuCap"))) {
        ibx_BF_ACC_ISU_SHRS.setValue(dma_bfStkcertIsuOneRes.get("bfAccIsuShrs"));
        ibx_BF_ACC_ISU_CAP.setValue(dma_bfStkcertIsuOneRes.get("bfAccIsuCap"));
    } else {
        //신규건...
        ibx_BF_ACC_ISU_SHRS.setValue(0);
        ibx_BF_ACC_ISU_CAP.setValue(0);
    }
};
