scwin.fn_setCheckboxData = function(obj, val) {
    if (val == 'Y') {
        obj.setValue(1);
    } else {
        obj.setValue(0);
    }
};
scwin.fn_getCheckboxData = function(obj) {
    if (!$c.util.isEmpty(obj.getValue())) {
        return 'Y';
    } else {
        return 'N';
    }
};
scwin.fn_read_sync = async function() {
    //var url = "/KindStk.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readKindStkIsuDtl&inputMessageId=KIND_STK_NEWLIST_SEARCH_OUT";
