scwin.fn_CheckForm = function() {
    var vCurDate = $c.date.getServerDateTime("yyyyMMdd");
    if (ibx_ISUR_CD.getValue() == "") {
        $c.win.alert("[법인코드] 항목값이  없습니다.");
        ibx_ISUR_CD.focus();
        return false;
    }
    if (sbx_LIST_METHD_TP_CD.getValue() == "") {
        $c.win.alert("[상장방식]을 선택하세요.");
        sbx_LIST_METHD_TP_CD.focus();
        return false;
    }
    if (ibx_ISU_CD.getValue() == "") {
        $c.win.alert("[종목]을 선택하세요.");
        img_ISU_CD.focus();
        return false;
    }
    if (ibx_ISU_SRT_CD.getValue() == "") {
        $c.win.alert("[종목단축코드]항목값이  없습니다."); //ibx_ISU_SRT_CD.focus();return false;

    }
    if (ibx_ISU_KOR_NM.getValue() == "") {
        $c.win.alert("[한글종목명]을 입력하세요.");
        ibx_ISU_KOR_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(ibx_ISU_KOR_NM, 60, "한글종목명")) return false;
    if (ibx_ISU_KOR_ABBRV.getValue() == "") {
        $c.win.alert("[한글종목약명]을 입력하세요.");
        ibx_ISU_KOR_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(ibx_ISU_KOR_ABBRV, 30, "한글종목약명")) return false;
    if (ibx_ISU_ENG_NM.getValue() == "") {
        $c.win.alert("[영문종목명]을 입력하세요.");
        ibx_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(ibx_ISU_ENG_NM, 60, "영문종목명")) return false;
    if (ibx_ISU_ENG_ABBRV.getValue() == "") {
        $c.win.alert("[영문종목약명]을 입력하세요.");
        ibx_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(ibx_ISU_ENG_ABBRV, 30, "영문종목약명")) return false;
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "1") {
        if (ibx_ISU_ENG_SYMBL.getValue() == "") {
            $c.win.alert("[영문종목심볼]을 입력하세요.");
            ibx_ISU_ENG_SYMBL.focus();
            return false;
        }
        if (!$c.lc.chkIsuSymblDoubleInput(ibx_ISU_ENG_SYMBL.getValue(), ibx_ISU_CD.getValue(), dma_isuRes)) {
            $c.win.alert("MSG_SYMBL_DOUBLE_INPUT");
            return false;
        }
    }
    if (ibx_LIST_DD.getValue() == "") {
        $c.win.alert("[상장일]을 입력하세요.");
        ibx_LIST_DD.focus();
        return false;
    }
    if (vCurDate >= ibx_LIST_DD.getValue()) {
        $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        ibx_LIST_DD.focus();
        return false;
    }
    if (ibx_ISU_DD.getValue() == "") {
        $c.win.alert("[발행일]을 입력하세요.");
        ibx_ISU_DD.focus();
        return false;
    }
    if (ibx_ISU_RND.getValue() == "") {
        $c.win.alert("[발행회차]를 입력하세요.");
        ibx_ISU_RND.focus();
        return false;
    }
    if (ibx_STKCERT_KIND_CD.getValue() == "") {
        $c.win.alert("[주식의종류]를 선택하세요.");
        ibx_STKCERT_KIND_CD.focus();
        return false;
    }
    if (ibx_STK_ISU_RSN_CD.getValue() == "") {
        $c.win.alert("[주식발행사유]를 선택하세요.");
        ibx_STK_ISU_RSN_CD.focus();
        return false;
    }

    ///*
    if (scwin.vSecugrpID != $c.lc.getGlbValue("SECUGRP_ID_MF") && scwin.vSecugrpID != $c.lc.getGlbValue("SECUGRP_ID_IF") && scwin.vSecugrpID != $c.lc.getGlbValue("SECUGRP_ID_DR")) {
        if (edt_PARVAL.getValue() == "") {
            $c.win.alert("[액면가]을 입력하세요.");
            edt_PARVAL.focus();
            return false;
        }

        //if (! fn_checkNumber(edt_PARVAL, '액면가')) return false;

    }
    if (ibx_ISU_PRC.getValue() == "") {
        $c.win.alert("[발행가]을 입력하세요.");
        ibx_ISU_PRC.focus();
        return false;
    }
    if (ibx_ISU_SHRS.getValue() == "") {
        $c.win.alert("[증감" + scwin.visuShrsLabelNm + "수]을 입력하세요.");
        ibx_ISU_SHRS.focus();
        return false;
    }
    if (scwin.vSecugrpID != $c.lc.getGlbValue("SECUGRP_ID_DR")) {
        if (ibx_ISU_CAP.getValue() == "") {
            $c.win.alert("[증감 상장자본금]을 입력하세요.");
            ibx_ISU_CAP.focus();
            return false;
        }
        if (ibx_ACC_ISU_SHRS.getValue() == "") {
            $c.win.alert("[변경후 상장" + scwin.visuShrsLabelNm + "수]을 입력하세요.");
            ibx_ACC_ISU_SHRS.focus();
            return false;
        }
        if (ibx_ACC_ISU_SHRS.getValue() == "0") {
            $c.win.alert("[변경후 상장" + scwin.visuShrsLabelNm + "수]값이 '0' 입니다. \n[증감 상장" + scwin.visuShrsLabelNm + "수]가 올바르게 입력되었는지 확인바랍니다.");
            ibx_ACC_ISU_SHRS.focus();
            return false;
        }
        if (ibx_ACC_ISU_CAP.getValue() == "") {
            $c.win.alert("[변경후 상장자본금]을 입력하세요.");
            ibx_ACC_ISU_CAP.focus();
            return false;
        }
        if (ibx_ACC_ISU_CAP.getValue() == "0") {
            $c.win.alert("[변경후 상장자본금]값이 '0' 입니다. '\n[증감 상장자본금]이 올바르게 입력되었는지 확인바랍니다.");
            ibx_ACC_ISU_CAP.focus();
            return false;
        }
    }
    if (ibx_DIV_RECK_DD1.getValue() == "") {
        $c.win.alert("[배당기산일1]을 입력하세요.");
        ibx_DIV_RECK_DD1.focus();
        return false;
    }
    if (ibx_NPARVALSTK_YN.getValue() == "Y") {
        var PER1STK_CAP = Number.parseFloat(ibx_PER1STK_CAP.getValue());
        var ISU_PRC = Number.parseFloat(ibx_ISU_PRC.getValue());
        if (PER1STK_CAP > ISU_PRC) {
            $c.win.alert('개별주당자본금은  발행가 이하로 입력해 주십시오.');
            ibx_PER1STK_CAP.focus();
            return false;
        }
        if (PER1STK_CAP < (ISU_PRC * 0.5)) {
            $c.win.alert('개별주당자본금은 발행가의 50% 이상으로 입력해 주십시오');
            ibx_PER1STK_CAP.focus();
            return false;
        }
    }
    return true;
};
