    //trs_Save.Action = $c.lc.fn_encodeNSession("/KindStk.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveKindStkIsu");
