scwin.calcuAccIsuShrs = function() {
    try {
        var vsum = Number.parseInt(ibx_BF_ACC_ISU_SHRS.getValue() ? ibx_BF_ACC_ISU_SHRS.getValue() : 0) 
            + Number.parseInt(ibx_ISU_SHRS.getValue() ? ibx_ISU_SHRS.getValue() : 0);
        //alert( "[vsum]"+vsum);
        ibx_ACC_ISU_SHRS.setValue(vsum)
    } catch (err) {
        $c.win.alert("[변경후 상장증권수 계산 중 오류]" + err);
    }
};
scwin.calcusuCap = function() {
    if (scwin.vSecugrpID == $c.lc.getGlbValue("SECUGRP_ID_DR")) {
        ibx_ISU_CAP.setValue('');
    } else {
        try {
            var vRsnCd = ibx_STK_ISU_RSN_CD.getValue();
            var vsum = 0;
            if (vRsnCd == '118' || //이익소각
                vRsnCd == '160' || //상호변경
                vRsnCd == '170' || //약면변합
                vRsnCd == '171') {
                //액면분할
                vsum = 0; //유가

            } else if (vRsnCd == '626' || //이익소각
                vRsnCd == '643' || //상호변경
                vRsnCd == '640' || //약면변합
                vRsnCd == '641') {
                //액면분할
                vsum = 0; //코스닥

            } else {
                if (scwin.vSecugrpID == $c.lc.getGlbValue("SECUGRP_ID_MF")|| scwin.vSecugrpID == $c.lc.getGlbValue("SECUGRP_ID_IF")) {
                    vsum = Number.parseFloat(ibx_ISU_PRC.getValue()) * Number.parseFloat(ibx_ISU_SHRS.getValue());
                } else {
                    vsum = Number.parseFloat(edt_PARVAL.getValue()) * Number.parseFloat(ibx_ISU_SHRS.getValue());
                }
            }
            //alert( "[증감자본금 vsum]"+vsum);
            ibx_ISU_CAP.setValue(vsum)
        } catch (err) {
            $c.win.alert("[증감 상장자본금 계산 중  오류]" + err);
        }
    }
};
scwin.calcuAccIsuCap = function() {
    if (scwin.vSecugrpID == $c.lc.getGlbValue("SECUGRP_ID_DR")) {
        ibx_ACC_ISU_CAP.setValue('');
    } else {
        try {
            var vRsnCd = ibx_STK_ISU_RSN_CD.getValue();
            var vsum = '';
            if (vRsnCd == '118' || //이익소각
                vRsnCd == '160' || //상호변경
                vRsnCd == '170' || //약면변합
                vRsnCd == '171') {
                //액면분할
                vsum = ibx_BF_ACC_ISU_CAP.getValue(); //유가
                ibx_ISU_CAP.setValue(0); //유가

            } else if (vRsnCd == '626' || //이익소각
                vRsnCd == '643' || //상호변경
                vRsnCd == '640' || //약면변합
                vRsnCd == '641') {
                //액면분할
                vsum = ibx_BF_ACC_ISU_CAP.getValue(); //코스닥
                ibx_ISU_CAP.setValue(0); //코스닥
            } else {
                scwin.calcusuCap();
                vsum = Number.parseFloat(ibx_BF_ACC_ISU_CAP.getValue()) + Number.parseFloat(ibx_ISU_CAP.getValue());
            }
            ibx_ACC_ISU_CAP.setValue(vsum);
        } catch (err) {
            $c.win.alert("[변경후 상장자본금 계산 중  오류]" + err);
        }
    }
};




