scwin.init = async function() {
    var parentWin = $c.win.getParent();
    var vCoBzProcsNo = parentWin.scwin.vBzProcsNo;
    scwin.vBzProcsNo = parentWin.clickBzProcsNo ? parentWin.clickBzProcsNo : "";
    scwin.vSecugrpID = parentWin.sbx_secugrpId.getValue();
    scwin.vPRELM_INVSTG_BZ_PROCS_NO = parentWin.dma_corpInfoRes.get("prelmInvstgBzProcsNo");
    scwin.vSPOT_ISU_TRD_MKT_TP_CD = parentWin.sbx_spotIsuTrdMktTpCd.getValue();
    ibx_ISUR_CD.setValue(parentWin.ibx_isurCd.getValue());
    ibx_COM_NM.setValue(parentWin.ibx_comNm.getValue());
    scwin.rowPos = parentWin.grd_issList.getFocusedRowIndex();

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    //buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    //buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    //buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제


    //resizeToWin() ;
    await scwin.fn_searchCode();
    await scwin.fn_SetComboCode();
    //$c.libRoundPanel.PanelToGroupBox(panel_Item);
    scwin.fn_setInitLabel();
    scwin.fn_setSumblComponent();
    if (scwin.vBzProcsNo != "") {
        scwin.fn_read_sync();
        // 보호예수읽어온다
        scwin.fn_prtdepo_read_sync();
    } else {
        //dts_Isu.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=KIND_STK_STKCERT_ISU_DTL_INOUT";
        //dts_Isu.reset();
        //dts_Isu.insertRow();

        if (vCoBzProcsNo == "") {
            $c.win.alert("먼저 회사정보를 입력후 종목정보를 입력바랍니다.");
            $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP); //disable 시킨다.
            scwin.btnStats = "error";
        } else {
            ibx_LIST_DD.setValue(parentWin.cal_listDd.getValue());
            var vlistClssCd = parentWin.sbx_listClssCd.getValue();
            var vListMethdTpCd;
            var vListMethdTpUpCd = vlistClssCd.substring(0, 1);
            vListMethdTpCd = $c.lc.getGlbValue("LIST_METHD_TP_CD_4");
            sbx_LIST_METHD_TP_CD.setValue(vListMethdTpCd);
        }
        var vCurDate = $c.date.getServerDateTime("yyyyMMdd");
        if (ibx_LIST_DD.getValue() <= vCurDate) {//disable 시킨다.
            $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP);
            scwin.btnStats = "error";
        }
        if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == '1') {
            //자동 settiong
            panel_ISU_ENG_SYMBL.show("");
            ibx_ISU_ENG_SYMBL.setValue(parentWin.ibx_isurSymbl.getValue());
        } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == '2') {
            panel_ISU_ENG_SYMBL.hide();
        }

        // 보호예수초기화
        scwin.fn_prtdepo_read_sync_setHeader();
    }
};
